// 基本面越线：family/foreign 实控 / OCF连续两年<1 / 支付率连续两年>payoutMax / 治理缺失 / dps缺失
const govMissing = !(t && t.governance);              // 缺 governance（无实控人用 'none' 表示合规，不算缺失）
const ocfs = (t && Array.isArray(t.ocfd2y)) ? t.ocfd2y : [];
const ocf2yMissing = !(ocfs.length >= 2 || (t && typeof t.ocfd2y === 'number'));
const ocfBreak = ocf2yBreak(t);
const payBreak = payout2yBreak(t);
const dpsMissing = !(mg && mg.dps > 0 && mg.targetBuyAbsolute > 0); // dps 未配置 → 无法算目标买价
r.dpsMissing = dpsMissing;
const fundBreak = (t && (t.governance === 'family' || t.governance === 'foreign'))
  || ocfBreak || payBreak
  || govMissing;
r.fundBreak = !!fundBreak;
r.govMissing = govMissing; r.ocf2yMissing = ocf2yMissing;
r.ocfBreak = ocfBreak; r.payBreak = payBreak;
// 信号分解：股息率达标(yldHit) 是唯一硬门槛；分位/布林带只作加分项（不单独触发买入）
const yldHit = (r.buyToTgtPct != null && r.buyToTgtPct >= 0);
// 分位样本量：不足 250 交易日时不计分
const pctEnough = (mg.histYldN == null || mg.histYldN >= 250);
const pctHit = (pctEnough && mg.yldPct != null && mg.yldPct >= 80);
r.pctSampleLow = !pctEnough;
const bollRaw = !!(r.boll60 && r.boll60.belowLower);
// 基本面越线时，布林下轨不参与计分
const bollHit = bollRaw && !fundBreak;
// 排序分：分位达标 +1、布林触底 +1；ocfd2y 缺失 −1（最低 0）。同分按 buyToTgtPct 降序。
let strength = (pctHit ? 1 : 0) + (bollHit ? 1 : 0);
if (ocf2yMissing) strength -= 1;
if (strength < 0) strength = 0;
r.marginStrength = strength;
// 一票否决：未达股息率绝对阈值 / 治理缺失 / 基本面越线 / dps缺失 → 不买
r.marginBuy = !!yldHit && !govMissing && !fundBreak && !dpsMissing;
r.yldHit = yldHit; r.pctHit = pctHit; r.bollHit = bollHit; r.bollRaw = bollRaw;
r.marginBonus = (pctHit ? '高股息分位' : '') +
  (bollHit ? (pctHit ? '、' : '') + '触布林下轨' : '') +
  (bollRaw && fundBreak ? (pctHit ? '、' : '') + '跌破下轨但基本面越线(不构成买点)' : '') +
  (ocf2yMissing ? (yldHit || pctHit || bollHit ? '、' : '') + '连续两年规则未校验(降权)' : '');

