tool_input.new_string:
function dpsOf(t, price) {
  if (!t) return null;
  if (t.dps != null && +t.dps > 0) return +t.dps;
  if (t.yld != null && price > 0) return price * +t.yld / 100;
  return null;
}

/* 宪法时序条款判定（字段类型：number=聚合值(最近两年min/max) 或 [y1,y2] 数组，兼容两种）
   ocfd2y: OCF/分红，< ocfMin(默认1) 越线；payout2y: 支付率%，> payoutMax(默认80) 越线 */
function _mThresh(key, dflt) { return (CFG && CFG.margin && CFG.margin[key] != null) ? +CFG.margin[key] : dflt; }
function ocf2yBreak(t) {
  if (!t) return false;
  const min = _mThresh('ocfdMin', +RULES.ocf_min || 1);
  const v = t.ocfd2y;
  if (typeof v === 'number') return v < min;
  if (Array.isArray(v) && v.length >= 2) return v.every(x => x != null && x < min);
  return false;
}
function payout2yBreak(t) {
  if (!t) return false;
  const max = _mThresh('payoutMax', 80);
  const v = t.payout2y;
  if (typeof v === 'number') return v > max;
  if (Array.isArray(v) && v.length >= 2) return v.every(x => x != null && x > max);
  return false;
}

