// 目标股息率：
//  dynamic(默认) = max(targetYldFloor, 近3年均值 + yldPadPct)，样本不足时用 targetYldFloor 兜底
//  fixed         = 直接用 targetYldFixed（未配则 targetYld，再未配则 floor），不看均值
const fixedYld = params.targetYld || 5.0;
const pad = params.yldPadPct != null ? params.yldPadPct : 1.0;      // 安全垫（百分点）
const floor = params.targetYldFloor != null ? params.targetYldFloor : fixedYld; // 下限
const mode = params.targetYldMode || 'dynamic';
const pctEnough = histY.length >= 250;
let targetYld, targetYldConst;
if (mode === 'fixed') {
  const fx = (params.targetYldFixed != null) ? +params.targetYldFixed
    : (params.targetYld != null ? +params.targetYld : floor);
  targetYld = fx;
  targetYldConst = '固定 ' + fmt(fx, 1) + '%';
} else if (avg != null && avg > 0 && pctEnough) {
  const raw = avg + pad;
  if (raw >= floor) {
    targetYld = raw;
    targetYldConst = '均值 ' + fmt(avg, 1) + '+垫 ' + fmt(pad, 1);
  } else {
    targetYld = floor;
    targetYldConst = '下限兜底；均值仅 ' + fmt(avg, 1);
  }
} else {
  targetYld = floor;
  targetYldConst = '均值样本不足（' + histY.length + '日），按下限 ' + fmt(floor, 1) + '% 兜底';
}

