if (reinvest) {
  if (buyShares <= 0 || buyPrice <= 0) { toast('再投资需填写买入股数和价格', true); return; }
  // A股最小 100 股且整数倍；不足 100 股的分红余额不再投资（只记分红）
  if (buyShares < 100 || buyShares % 100 !== 0) { toast('买入股数须 ≥100 且为 100 的整数倍（不足部分只记分红）', true); return; }
  // #6 再投资金额（N×价格+费用）不得超过到账分红净额（amount - tax）
  const netDiv = amount - tax;
  const estFee = calcFee('buy', buyShares * buyPrice);
  if (buyShares * buyPrice + estFee > netDiv + 0.01) {
    const maxSh = Math.floor((netDiv - calcFee('buy', netDiv)) / buyPrice / 100) * 100;
    toast('再投资金额超出分红净额 ' + fmt(netDiv, 2) + ' 元（含费用）；最多可买约 ' + fmt(Math.max(0, maxSh), 0) + ' 股，超出部分需额外补现金', true);
    return;
  }
  // #8 买入日期不得早于分红日期
  if (buyDate && date && buyDate < date) { toast('买入日期不能早于分红日期（钱尚未到账）', true); return; }
}

