function exportHoldCsv() {
  // #12 持仓快照只导出实际持仓（shares>0），避免目标池未持仓的 0 股行干扰年度复查
  const rows = rowsNow().filter(r => r.shares > 0);
  if (!rows.length) { toast('没有持仓数据', true); return; }
  const GCN = { state: '国资', none: '无实控人', family: '家族', foreign: '外资' };
  const data = rows.map(r => [(r.accts && r.accts.length ? r.accts.map(acctName).join('/') : '合计'),
    r.name, r.code, r.ind, r.shares, r.costPrice ? r.costPrice.toFixed(4) : '',
    r.price || '', r.mv ? r.mv.toFixed(2) : '', r.pnl != null ? r.pnl.toFixed(2) : '',
    r.pnlRate != null ? r.pnlRate.toFixed(2) + '%' : '', r.divNet ? r.divNet.toFixed(2) : '',
    (r.t && r.t.governance) ? (GCN[r.t.governance] || r.t.governance) : '未标注']); // #13 渲染中文
  _downloadCsv('持仓快照', ['账户', '名称', '代码', '行业', '数量', '成本价', '现价', '市值', '浮动盈亏', '收益率', '累计分红', '实控人'], data);
}

