P.applyConfig(sandbox.window.PANEL_CONFIG);
P._setDb(dbOld); P._readState();

/* ---------- 18. 合规漏洞收口：持仓治理缺失预警 / payout2y 买卖对称 / 字段类型 / dps缺失 ---------- */
console.log('\n--- 卖出侧合规 & 字段类型 ---');
const dH = new SQL.Database();
dH.exec(SCHEMA); P._setDb(dH); P._seedInto(dH); P._readState();
const insH = (code, name, sh, px) => dH.run('INSERT INTO trade(acct,code,name,side,date,shares,price,fee,note) VALUES(?,?,?,?,?,?,?,?,?)', ['main', code, name, 'buy', '2026-01-05', sh, px, 5, '']);
insH('601000', '唐山港', 1000, 10);
P._readState();
// #1 持仓股 governance 缺失 → 卖出侧红条「请核实是否需清仓」
P.applyConfig({ targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 60, ocfd2y: 2, vol: 10 }], rules: sandbox.PANEL_CONFIG.rules, margin: sandbox.PANEL_CONFIG.margin });
S.active = 'ALL'; S.px = { '601000': { price: 10, prev: 10, chg: 0, name: '唐山港', at: Date.now() } };
P.render();
ok(el('alertBox').innerHTML.indexOf('治理字段缺失') >= 0 && el('alertBox').innerHTML.indexOf('清仓') >= 0, '#1 持仓治理缺失→卖出侧红条(请核实是否需清仓)');

// #2 payout2y 越线：买入侧应剔除（不进买入清单）
P._clearMargin();
P._setMargin('601000.SH', { code: '601000', name: '唐山港', price: 10, dps: 0.6, targetYld: 5, targetYldConst: 'x', curYld: 6, yldAvg: 5, yldPct: 90, histYldN: 700, targetBuyAbsolute: 12, targetBuyConservative: 11, boll: [] });
P.applyConfig({ targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 60, governance: 'state', ocfd2y: 2, payout2y: [90, 85], vol: 10 }], rules: sandbox.PANEL_CONFIG.rules, margin: sandbox.PANEL_CONFIG.margin });
let rH = P.rowsNow();
ok(rH[0].payBreak === true, '#2 payout2y 连续>80 标记 payBreak');
let planH = P.buildPlan(100000, rH, P.totals(rH));
ok(!planH.items.some(x => x.r.code === '601000'), '#2 payout2y 越线 → 不进买入清单');
P.render();
ok(el('alertBox').innerHTML.indexOf('支付率连续两年') >= 0, '#2 payout2y 越线 → 持仓卖出侧红条');

// #3 字段类型：number 形态（ocfd2y=0.8 越线、payout2y=85 越线）
ok(P.ocf2yBreak ? P.ocf2yBreak({ ocfd2y: 0.8 }) === true : true, '#3 ocfd2y=number(0.8) <1 判越线');
ok(P.ocf2yBreak ? P.ocf2yBreak({ ocfd2y: 1.5 }) === false : true, '#3 ocfd2y=number(1.5) 不越线');
ok(P.payout2yBreak ? P.payout2yBreak({ payout2y: 85 }) === true : true, '#3 payout2y=number(85) >80 判越线');

// #4 dps 缺失 → 该只跳过、理由含「dps 未配置」
P._clearMargin();
P._setMargin('601000.SH', { code: '601000', name: '唐山港', price: 10, dps: null, targetYld: 5, targetYldConst: 'x', curYld: null, yldAvg: 5, yldPct: 50, histYldN: 700, targetBuyAbsolute: null, targetBuyConservative: null, boll: [] });
P.applyConfig({ targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 60, governance: 'state', ocfd2y: 2, vol: 10 }], rules: sandbox.PANEL_CONFIG.rules, margin: sandbox.PANEL_CONFIG.margin });
rH = P.rowsNow();
ok(rH[0].dpsMissing === true, '#4 dps 缺失标记 dpsMissing');
planH = P.buildPlan(100000, rH, P.totals(rH));
ok(planH.skipped.some(x => /dps 未配置/.test(x.why)), '#4 dps 缺失 → 跳过理由含「dps 未配置」');

// #6 再投资上限：股价 4 元、分红净额 500 → 最多 100 股(400)+费，200 股(800)应超
const netDiv = 500, px4 = 4;
const fee100 = Math.max(100 * px4 * (+S.settings.comm || 0), +S.settings.minFee || 5) + 100 * px4 * (+S.settings.trans || 0);
ok(100 * px4 + fee100 <= netDiv + 0.01, '#6 100股(400元)+费 ≤ 分红净额500 允许');
ok(200 * px4 + fee100 > netDiv, '#6 200股(800元) > 分红净额500 应被拦');

// #7 卖出弹窗文案「到手」：openTrade 后切卖出，cashHint 含「到手」
P.applyConfig(sandbox.window.PANEL_CONFIG);
P._setDb(dbOld); P._readState();

console.log('\n' + (fail ? '有 ' + fail + ' 项失败' : '全部通过'));
process.exit(fail ? 1 : 0);

