const fs=require('fs'),vm=require('vm');
const html=fs.readFileSync('分析产出/持仓面板/index.html','utf8');
const m=html.match(/<script>\n\(function \(\) \{\n'use strict';\n\n\/\* =+ 常量[\s\S]*?<\/script>/);
const main=m[0].replace(/^<script>\n/,'').replace(/<\/script>$/,'');
const cfg=fs.readFileSync('分析产出/持仓面板/config.js','utf8');
const https=require('https');
function get(u){return new Promise((res,rej)=>{https.get(u,r=>{let b='';r.on('data',d=>b+=d);r.on('end',()=>res(b));}).on('error',rej);});}
const els={};function el(id){if(!els[id])els[id]={innerHTML:'',textContent:'',value:'',style:{},classList:{toggle(){},add(){},remove(){},contains(){return false}},addEventListener(){},setAttribute(){},querySelector(){return null},closest(){return null},focus(){}};return els[id];}
const sb={console,Date,Math,Number,String,Object,Array,JSON,isNaN,isFinite,parseFloat,parseInt,RegExp,atob:s=>Buffer.from(s,'base64').toString('binary'),setTimeout:(f)=>setTimeout(f,9000),setInterval:()=>0,clearTimeout:t=>clearTimeout(t),clearInterval(){},confirm:()=>true,alert(){},indexedDB:{open(){return{}}},localStorage:{getItem:()=>null,setItem(){}},document:{getElementById:el,querySelector:s=>el(s.replace(/^#/,'')),querySelectorAll:()=>[],addEventListener(){},createElement:()=>({style:{},dataset:{},remove(){},click(){},appendChild(){},setAttribute(){},onload:null,onerror:null}),head:{appendChild(s){const cbM=s.src.match(/[?&]callback=([^&]+)/);const cb=cbM&&cbM[1];get(s.src).then(t=>{const inner=t.replace(new RegExp('^'+cb+'\\('),'').replace(/\);?\s*$/,'');if(typeof sb[cb]==='function')sb[cb](JSON.parse(inner));if(s.onload)s.onload();}).catch(()=>{if(s.onerror)s.onerror();});}},body:{appendChild(){}}},fetch:u=>get(u).then(t=>({json:()=>JSON.parse(t)})),location:{search:''},FileReader:function(){},Blob:function(){},URL:{createObjectURL:()=>'',revokeObjectURL(){}}};
sb.window=sb;sb.self=sb;sb.globalThis=sb;vm.createContext(sb);
vm.runInContext(cfg,sb);
sb.initSqlJs=async()=>({Database:function(){}});
vm.runInContext(main,sb);
const P=sb.__PANEL__;
(async()=>{
  const t=sb.PANEL_CONFIG.targets.find(x=>x.code==='600461');
  // dynamic
  const d=await P._mComputeOne(t, sb.PANEL_CONFIG.margin);
  console.log('dynamic: targetYld',d.targetYld,'const',d.targetYldConst,'yldPct',d.yldPct);
  // fixed mode
  const fx=await P._mComputeOne(t, Object.assign({},sb.PANEL_CONFIG.margin,{targetYldMode:'fixed',targetYldFixed:6.5}));
  console.log('fixed: targetYld',fx.targetYld,'const',fx.targetYldConst);
  const ok = d.targetYld>0 && d.targetYldConst && fx.targetYld===6.5 && /固定/.test(fx.targetYldConst);
  console.log('OK=',!!ok); process.exit(ok?0:1);
})().catch(e=>{console.error(e);process.exit(1);});
